package com.example.nafa;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.*;
public class BorrowRequestsActivity extends Activity{
 LinearLayout list;FirebaseFirestore db;String uid;
 public void onCreate(Bundle b){super.onCreate(b);db=FirebaseFirestore.getInstance();uid=FirebaseAuth.getInstance().getUid();ScrollView s=Ui.scroll(this);list=Ui.col(this);list.setPadding(16,20,16,20);s.addView(list);setContentView(s);load();}
 void load(){list.addView(Ui.title(this,"طلبات الاستعارة"));db.collection("borrow_requests").whereEqualTo("borrowerId",uid).get().addOnSuccessListener(a->{for(DocumentSnapshot d:a)add(d,false);});db.collection("borrow_requests").whereEqualTo("ownerId",uid).get().addOnSuccessListener(a->{for(DocumentSnapshot d:a)add(d,true);});}
 void add(DocumentSnapshot d,boolean incoming){LinearLayout c=Ui.col(this);c.setBackground(getDrawable(R.drawable.bg_card));TextView s=Ui.text(this,(incoming?"طلب وارد":"طلب مرسل")+" • "+d.getString("status"),17,getColor(R.color.nafa_text),true);c.addView(s,new LinearLayout.LayoutParams(-1,45));TextView m=Ui.text(this,d.getString("message"),13,getColor(R.color.nafa_hint),false);c.addView(m,new LinearLayout.LayoutParams(-1,55));if(incoming&&"pending".equals(d.getString("status"))){LinearLayout r=Ui.row(this);Button ok=Ui.button(this,"قبول",true),no=Ui.button(this,"رفض",false);r.addView(ok,new LinearLayout.LayoutParams(0,52,1));r.addView(no,new LinearLayout.LayoutParams(0,52,1));c.addView(r);ok.setOnClickListener(v->respond(d.getId(),"accepted"));no.setOnClickListener(v->respond(d.getId(),"rejected"));}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,8);list.addView(c,p);}
 void respond(String id,String st){db.collection("borrow_requests").document(id).update("status",st,"respondedAt",FieldValue.serverTimestamp(),"updatedAt",FieldValue.serverTimestamp()).addOnSuccessListener(v->{Toast.makeText(this,st.equals("accepted")?"تم قبول الطلب":"تم رفض الطلب",Toast.LENGTH_SHORT).show();recreate();});}
}